# >>> CHOICES
_choice_affinity() {
    local count
    count="$(getconf _NPROCESSORS_ONLN 2>/dev/null)"
    [[ "$count" =~ ^[0-9]+$ ]] || return 0
    gawk -v count="$count" 'BEGIN { for (i = 0; i < count; i++) print i }'
}

_choice_bind_dev() {
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
    elif [[ -d /sys/class/net ]]; then
        find /sys/class/net -mindepth 1 -maxdepth 1 | sed 's|.*/||'
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_congestion() {
    if [[ -r /proc/sys/net/ipv4/tcp_available_congestion_control ]]; then
        gawk '{ for (i = 1; i <= NF; i++) print $i }' /proc/sys/net/ipv4/tcp_available_congestion_control
    fi
}

_choice_dscp() {
    printf '%s\n' af11 af12 af13 af21 af22 af23 af31 af32 af33 af41 af42 af43 \
        cs1 cs2 cs3 cs4 cs5 cs6 cs7 ef va lowdelay throughput reliability
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
